#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package SSH.NET@2020.0.1 #:package Microsoft.Extensions.Hosting@8.0.0 #:package System.Threading.Channels@7.0.0 #:property LangVersion=preview #:property TargetFramework=net11.0 #:property Nullable=enable  using Renci.SshNet; using Microsoft.Extensions.DependencyInjection; using Microsoft.Extensions.Hosting; using System.Threading.Channels; using System.Diagnostics;  /* - 审计日志 ：记录所有命令执行和文件操作 - 权限控制 ：基于角色的命令执行权限管理 - 会话加密 ：使用更安全的加密算法 - 双因素认证 ：增强安全性 - 操作审批 ：关键操作需要审批 - 实时监控 ：连接状态和资源使用情况监控 - 自动补全 ：命令自动补全和历史记录 - 批量操作 ：支持同时对多个设备执行命令 - 插件系统 ：可扩展的命令和功能插件 - Web管理界面 ：可视化设备管理 */ public class RttyOptions {     public string Host { get; set; }     public int Port { get; set; } = 22;     public string Username { get; set; }     public string Password { get; set; }     public int MaxConnections { get; set; } = 5;     public int RetryCount { get; set; } = 3;     public TimeSpan RetryInterval { get; set; } = TimeSpan.FromSeconds(5);     public TimeSpan HeartbeatInterval { get; set; } = TimeSpan.FromSeconds(30);     public TimeSpan ConnectionTimeout { get; set; } = TimeSpan.FromMinutes(1);     public string ConnectionStorePath { get; set; } = "connections.json";     public List<string> DangerousCommands { get; set; } = new()     {         "rm -rf",         ":(){ :|:& };:", // fork bomb         "mkfs",         "dd if=/dev/random",         "chmod -R 777 /"     };     public AuditLogOptions AuditLog { get; set; } = new(); }  public class AuditLogOptions {     public bool Enabled { get; set; } = true;     public TimeSpan RetentionPeriod { get; set; } = TimeSpan.FromDays(30); }  // 实现IAuditLogger接口 public interface IAuditLogger {     Task LogAsync(AuditLogEntry entry); }  public class AuditLogEntry {     public DateTime Timestamp { get; set; }     public string User { get; set; }     public string Command { get; set; }     public string Result { get; set; } } {     private readonly RttyOptions _options;     private readonly Channel<SshCommand> _commandChannel;     private readonly ObjectPool<SshClient> _clientPool;     private readonly CancellationTokenSource _cts = new();     private Task _processingTask;     private readonly ConcurrentDictionary<string, ConnectionInfo> _activeConnections = new();     private readonly Timer _heartbeatTimer;     private readonly Timer _timeoutTimer;     private readonly ILogger<RttyService> _logger;     private readonly string _connectionStorePath;      public RttyService(RttyOptions options, ILogger<RttyService> logger)     {         _options = options;         _logger = logger;         _commandChannel = Channel.CreateBounded<SshCommand>(new BoundedChannelOptions(1000)         {             FullMode = BoundedChannelFullMode.Wait,             SingleReader = false,             SingleWriter = false         });          _clientPool = new ObjectPool<SshClient>(() =>          {             var client = new SshClient(_options.Host, _options.Port, _options.Username, _options.Password);             client.Connect();             return client;         }, maxSize: _options.MaxConnections);         _connectionStorePath = options.ConnectionStorePath;         _heartbeatTimer = new Timer(SendHeartbeat, null,              TimeSpan.Zero, options.HeartbeatInterval);         _timeoutTimer = new Timer(CheckTimeouts, null,              TimeSpan.Zero, TimeSpan.FromSeconds(10));                  LoadConnections();     }      private void LoadConnections()     {         if (File.Exists(_connectionStorePath))         {             var json = File.ReadAllText(_connectionStorePath);             var connections = JsonSerializer.Deserialize<List<ConnectionInfo>>(json);             foreach (var conn in connections)             {                 _activeConnections.TryAdd(conn.DeviceId, conn);             }         }     }      private void SaveConnections()     {         var connections = _activeConnections.Values.ToList();         var json = JsonSerializer.Serialize(connections);         File.WriteAllText(_connectionStorePath, json);     }      private void SendHeartbeat(object state)     {         foreach (var (deviceId, _) in _activeConnections)         {             try             {                 ExecuteCommandAsync(deviceId, "echo heartbeat").Wait();             }             catch (Exception ex)             {                 _logger.LogWarning(ex, "心跳检测失败: {DeviceId}", deviceId);                 _activeConnections.TryRemove(deviceId, out _);             }         }     }      private void CheckTimeouts(object state)     {         var timeoutThreshold = DateTime.Now - _options.ConnectionTimeout;         foreach (var (deviceId, conn) in _activeConnections)         {             if (conn.LastConnected < timeoutThreshold)             {                 _logger.LogInformation("连接超时: {DeviceId}", deviceId);                 _activeConnections.TryRemove(deviceId, out _);             }         }     }      public async Task ExecuteCommandAsync(string deviceId, string command)     {         using var client = _clientPool.Get();         var cmd = client.CreateCommand(command);         cmd.CommandExecuted += (sender, args) =>          {             _hubContext.Clients.Group(deviceId).SendAsync("ReceiveOutput", args.Result);         };                  await cmd.ExecuteAsync();     } }  public static class ServiceCollectionExtensions {     public static IServiceCollection AddRttyServices(this IServiceCollection services, Action<RttyOptions> configure)     {         var options = new RttyOptions();         configure(options);                  services.AddSingleton(options);         // 扩展方法         public static IServiceCollection AddRttyServices(this IServiceCollection services) {             services.AddSingleton<IRttyService, RttyService>();             services.AddSingleton<IAuditLogger, DatabaseAuditLogger>();             services.AddSingleton<IPermissionValidator, RoleBasedPermissionValidator>();         services.AddHostedService(provider => provider.GetRequiredService<IRttyService>() as RttyService);                  // 添加危险命令验证器         services.AddSingleton<IDangerousCommandValidator, DangerousCommandValidator>();         return services;     } }  public interface IDangerousCommandValidator {     bool IsDangerous(string command); }  public class DangerousCommandValidator : IDangerousCommandValidator {     private readonly RttyOptions _options;     private readonly Regex _dangerousPatterns;      public DangerousCommandValidator(RttyOptions options)     {         _options = options;         var patterns = string.Join("|", _options.DangerousCommands             .Select(Regex.Escape));         _dangerousPatterns = new Regex($"({patterns})",              RegexOptions.IgnoreCase | RegexOptions.Compiled);     }      public bool IsDangerous(string command)     {         return !string.IsNullOrWhiteSpace(command) &&                 _dangerousPatterns.IsMatch(command);     } }  public class AuditLog {     public string Id { get; set; } = Guid.NewGuid().ToString();     public string DeviceId { get; set; }     public string Command { get; set; }     public string User { get; set; }     public DateTime Timestamp { get; set; } = DateTime.UtcNow;     public bool IsSuccessful { get; set; } }  public interface IAuditLogger {     Task LogAsync(AuditLog log, CancellationToken ct = default); }  public class PermissionOptions {     public Dictionary<string, List<string>> RoleCommands { get; set; } = new(); }  // 权限验证接口 public interface IPermissionValidator {     Task<bool> HasPermissionAsync(string user, string command); }  // 在RttyService中集成 public class RttyService : IRttyService {     private readonly IPermissionValidator _permissionValidator;          public async Task<string> ExecuteCommandAsync(string command) {         if (!await _permissionValidator.HasPermissionAsync(_currentUser, command)) {             throw new UnauthorizedAccessException();         }         _hubContext.Clients.Group(deviceId).SendAsync("ReceiveOutput", args.Result);                  await cmd.ExecuteAsync();                  await _auditLogger.LogAsync(new AuditLog         {             DeviceId = deviceId,             Command = command,             User = userRole,             IsSuccessful = true         }, ct);     } }  builder.Services.AddSignalR();  var app = builder.Build(); app.MapHub<TerminalHub>("/terminalHub");   // 使用AES-GCM加密算法 // 实现AES-GCM加密算法的Encrypt和Decrypt方法 public class SecureSessionChannel : IDisposable {     private readonly AesGcm _aesGcm;     private readonly byte[] _key;          public SecureSessionChannel(byte[] key) {         if (key.Length != 32) throw new ArgumentException("Key must be 256-bit (32 bytes)");         _key = key;         _aesGcm = new AesGcm(_key);     }          public byte[] Encrypt(byte[] plaintext) {         var nonce = new byte[AesGcm.NonceByteSizes.MaxSize];         RandomNumberGenerator.Fill(nonce);                  var tag = new byte[AesGcm.TagByteSizes.MaxSize];         var ciphertext = new byte[plaintext.Length];                  _aesGcm.Encrypt(nonce, plaintext, ciphertext, tag);                  // 组合nonce + ciphertext + tag         var result = new byte[nonce.Length + ciphertext.Length + tag.Length];         Buffer.BlockCopy(nonce, 0, result, 0, nonce.Length);         Buffer.BlockCopy(ciphertext, 0, result, nonce.Length, ciphertext.Length);         Buffer.BlockCopy(tag, 0, result, nonce.Length + ciphertext.Length, tag.Length);                  return result;     }          public byte[] Decrypt(byte[] encryptedData) {         // 解析nonce (12 bytes) + ciphertext + tag (16 bytes)         var nonce = new byte[AesGcm.NonceByteSizes.MaxSize];         var tag = new byte[AesGcm.TagByteSizes.MaxSize];         var ciphertext = new byte[encryptedData.Length - nonce.Length - tag.Length];                  Buffer.BlockCopy(encryptedData, 0, nonce, 0, nonce.Length);         Buffer.BlockCopy(encryptedData, nonce.Length, ciphertext, 0, ciphertext.Length);         Buffer.BlockCopy(encryptedData, nonce.Length + ciphertext.Length, tag, 0, tag.Length);                  var plaintext = new byte[ciphertext.Length];         _aesGcm.Decrypt(nonce, ciphertext, tag, plaintext);                  return plaintext;     }          public void Dispose() {         _aesGcm.Dispose();     } }  // DI集成 public static IServiceCollection AddSecureSessionChannel(this IServiceCollection services, byte[] key) {     services.AddSingleton(new SecureSessionChannel(key));     return services; }
